@@ -0,0 +1,67 @@
+import React from "react";
+import { GalleryVerticalEnd } from "lucide-react";
+import { Button } from "@/components/ui/button";
+import { Input } from "@/components/ui/input";
+import { Label } from "@/components/ui/label";
+
+type Params = {
+  policy: string;
+};
+
+export default function CustomerPortalLoginPage({
+  params,
+}: {
+  params: Params;
+}) {
+  const { policy } = params;
+
+  return (
+    <div className="flex min-h-svh flex-col items-center justify-center gap-6 bg-background p-6 md:p-10">
+      <div className="w-full max-w-sm">
+        <LoginForm policy={policy} />
+      </div>
+    </div>
+  );
+}
+
+function LoginForm({ policy }: { policy: string }) {
+  return (
+    <div className="flex flex-col gap-6">
+      <form method="post" action={`/p/access/${policy}`}>
+        <div className="flex flex-col gap-6">
+          <div className="flex flex-col items-center gap-2">
+            <a
+              href="#"
+              className="flex flex-col items-center gap-2 font-medium"
+            >
+              <div className="flex h-8 w-8 items-center justify-center rounded-md">
+                <GalleryVerticalEnd className="size-6" />
+              </div>
+              <span className="sr-only">Acme Inc.</span>
+            </a>
+            <h1 className="text-xl font-bold">Welcome to Acme Inc.</h1>
+            <div className="text-center text-sm">
+              Enter your email and we will send you a link directly to your
+              customer portal.
+            </div>
+          </div>
+          <div className="flex flex-col gap-6">
+            <div className="grid gap-2">
+              <Label htmlFor="email">Email</Label>
+              <Input
+                name="email"
+                type="email"
+                placeholder="m@example.com"
+                required
+              />
+              <Input name="passcode" placeholder="passcode" required />
+            </div>
+            <Button type="submit" className="w-full">
+              Login
+            </Button>
+          </div>
+        </div>
+      </form>
+    </div>
+  );
+}

